mapper.select:
SELECT C.COMPANY_NM , E.EMAIL , E.EMP_NM , SF_GET_CODE_NM('ko-KR', '03000', E.POS_CD, E.COMPANY_CD, E.DOMAIN_ID) AS POS_NM , D.DEPT_NM , E.MANUAL_MNG_YN , E.HIDDEN_YN FROM EMP_MASTER E INNER JOIN DEPT_MASTER D ON (E.DEPT_CD = D.DEPT_CD AND E.COMPANY_CD = D.COMPANY_CD AND E.DOMAIN_ID = D.DOMAIN_ID) INNER JOIN COMPANY_MASTER C ON (E.COMPANY_CD = C.COMPANY_CD AND E.DOMAIN_ID = C.DOMAIN_ID)
E.DOMAIN_ID = #{domainId} AND E.COMPANY_CD = #{companyCd}
AND D.DEPT_CD = #{deptCd}
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
AND E.EMAIL LIKE REPLACE(CONCAT('%', #{email}, '%'), ' ','')
ORDER BY DEPT_ORD, D.DEPT_CD, DEPT_NM, EMP_NM
LIMIT #{start}, #{length}

SELECT 
	COUNT(*)
FROM EMP_MASTER E
	INNER JOIN DEPT_MASTER D ON (E.DEPT_CD = D.DEPT_CD AND E.COMPANY_CD = D.COMPANY_CD AND E.DOMAIN_ID = D.DOMAIN_ID)
	INNER JOIN COMPANY_MASTER C ON (E.COMPANY_CD = C.COMPANY_CD AND E.DOMAIN_ID = C.DOMAIN_ID)

	E.DOMAIN_ID = #{domainId}
	AND E.COMPANY_CD = #{companyCd}

		AND D.DEPT_CD = #{deptCd}


		AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')


		AND E.EMAIL LIKE REPLACE(CONCAT('%', #{email}, '%'), ' ','')

SELECT C.COMPANY_NM , E.COMPANY_CD , E.EMAIL , E.EMP_NM , SF_GET_CODE_NM('ko-KR', '03000', E.POS_CD, E.COMPANY_CD, E.DOMAIN_ID) AS POS_NM , D.DEPT_NM , CASE WHEN COUNT(*) > 1 THEN 'ROLE_ADMIN' ELSE 'ROLE_USER' END AS AUTHORITY_NAME FROM EMP_MASTER E INNER JOIN DEPT_MASTER D ON (E.DEPT_CD = D.DEPT_CD AND E.COMPANY_CD = D.COMPANY_CD AND E.DOMAIN_ID = D.DOMAIN_ID) INNER JOIN COMPANY_MASTER C ON (E.COMPANY_CD = C.COMPANY_CD AND E.DOMAIN_ID = C.DOMAIN_ID) INNER JOIN EMP_AUTHORITY A ON (E.COMPANY_CD = A.COMPANY_CD AND E.DOMAIN_ID = A.DOMAIN_ID AND E.EMAIL = A.EMAIL)
E.DOMAIN_ID = #{domainId} AND E.COMPANY_CD = #{companyCd}
AND D.DEPT_CD = #{deptCd}
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
AND E.EMAIL LIKE REPLACE(CONCAT('%', #{email}, '%'), ' ','')
GROUP BY E.EMAIL HAVING AUTHORITY_NAME = 'ROLE_USER' ORDER BY DEPT_ORD, D.DEPT_CD, DEPT_NM, EMP_NM
LIMIT #{start}, #{length}

SELECT COUNT(*) FROM ( SELECT C.COMPANY_NM , E.COMPANY_CD , E.EMAIL , E.EMP_NM , SF_GET_CODE_NM('ko-KR', '03000', E.POS_CD, E.COMPANY_CD, E.DOMAIN_ID) AS POS_NM , D.DEPT_NM , CASE WHEN COUNT(*) > 1 THEN 'ROLE_ADMIN' ELSE 'ROLE_USER' END AS AUTHORITY_NAME FROM EMP_MASTER E INNER JOIN DEPT_MASTER D ON (E.DEPT_CD = D.DEPT_CD AND E.COMPANY_CD = D.COMPANY_CD AND E.DOMAIN_ID = D.DOMAIN_ID) INNER JOIN COMPANY_MASTER C ON (E.COMPANY_CD = C.COMPANY_CD AND E.DOMAIN_ID = C.DOMAIN_ID) INNER JOIN EMP_AUTHORITY A ON (E.COMPANY_CD = A.COMPANY_CD AND E.DOMAIN_ID = A.DOMAIN_ID AND E.EMAIL = A.EMAIL)
E.DOMAIN_ID = #{domainId} AND E.COMPANY_CD = #{companyCd}
AND D.DEPT_CD = #{deptCd}
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
AND E.EMAIL LIKE REPLACE(CONCAT('%', #{email}, '%'), ' ','')
GROUP BY E.EMAIL HAVING AUTHORITY_NAME = 'ROLE_USER' ORDER BY DEPT_ORD, D.DEPT_CD, DEPT_NM, EMP_NM ) A

mapper.insert:
INSERT
	EMP_AUTHORITY (
		DOMAIN_ID
		, COMPANY_CD
		, EMAIL
		, AUTHORITY_NAME
		, UPDATE_USR
		, UPDATE_DT
		, CREATE_USR
		, CREATE_DT
	)
	VALUES (
		#{domainId}
		, #{companyCd}
		, #{email}
		, "ROLE_ADMIN"
		, #{createUsr}
		, NOW()
		, #{createUsr}
		, NOW()
	)

mapper.delete:
DELETE FROM
	EMP_AUTHORITY

	DOMAIN_ID = #{domainId}
	AND COMPANY_CD = #{companyCd}
	AND EMAIL = #{email}
	AND AUTHORITY_NAME = "ROLE_ADMIN"

DELETE FROM
	EMP_MASTER

	DOMAIN_ID = #{domainId}
	AND COMPANY_CD = #{companyCd}
	AND (MANUAL_MNG_YN = 'N' OR MANUAL_MNG_YN IS NULL)

DELETE FROM
	EMP_AUTHORITY

	DOMAIN_ID = #{domainId}
	AND COMPANY_CD = #{companyCd}
	AND AUTHORITY_NAME = "ROLE_USER"
	AND EMAIL IN (SELECT EMAIL FROM EMP_MASTER WHERE MANUAL_MNG_YN = 'N' OR MANUAL_MNG_YN IS NULL)

mapper.update:
UPDATE
	EMP_MASTER


		MANUAL_MNG_YN = #{manualMngYn}


		, HIDDEN_YN = #{hiddenYn}

	, UPDATE_USR = #{updateUsr}
	, UPDATE_DT = NOW()


	DOMAIN_ID = #{domainId}
	AND COMPANY_CD = #{companyCd}
	AND EMAIL = #{email}
